import{_ as e,o as a,c as i,a2 as d}from"./chunks/framework.D3fmyz3M.js";const h=JSON.parse('{"title":"技术演进","description":"从 iframe 到 Module Federation，理解每种方案出现的动因。","frontmatter":{"title":"技术演进","description":"从 iframe 到 Module Federation，理解每种方案出现的动因。"},"headers":[],"relativePath":"guide/evolution.md","filePath":"guide/evolution.md","lastUpdated":1792674288000}'),o={name:"guide/evolution.md"};function r(n,t,l,s,p,u){return a(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="技术演进" tabindex="-1">技术演进 <a class="header-anchor" href="#技术演进" aria-label="Permalink to &quot;技术演进&quot;">​</a></h1><p>微前端不是一次发明出来的，而是被一个个具体问题推着演化。理解“为什么出现”，比记住“怎么配置”更重要。</p><h2 id="时间线" tabindex="-1">时间线 <a class="header-anchor" href="#时间线" aria-label="Permalink to &quot;时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>方案</th><th>解决的问题</th><th>留下的问题</th></tr></thead><tbody><tr><td>早期</td><td>iframe</td><td>彻底隔离，天然独立部署</td><td>通信、路由、弹窗、体验</td></tr><tr><td>2015 前后</td><td>路由分发</td><td>按路径挂不同应用</td><td>切换整页刷新，状态丢失</td></tr><tr><td>2016</td><td>Web Components</td><td>浏览器级组件封装</td><td>生态工具链、跨框架细节</td></tr><tr><td>2017</td><td>single-spa</td><td>统一生命周期与路由调度</td><td>无沙箱、无样式隔离、无 HTML Entry</td></tr><tr><td>2018</td><td>qiankun</td><td>HTML Entry + 沙箱 + 样式隔离</td><td>接入约束、UMD 构建、调试复杂</td></tr><tr><td>2019+</td><td>Module Federation</td><td>构建时模块共享，依赖去重</td><td>构建耦合、部署顺序、共享版本</td></tr><tr><td>2020+</td><td>micro-app</td><td>类 Web Component 接入，改造成本低</td><td>Shadow DOM 兼容细节、生态</td></tr><tr><td>2021+</td><td>wujie</td><td>iframe 执行 JS + Shadow DOM 渲染</td><td>架构较重、调试心智负担</td></tr></tbody></table><h2 id="每一代的核心动机" tabindex="-1">每一代的核心动机 <a class="header-anchor" href="#每一代的核心动机" aria-label="Permalink to &quot;每一代的核心动机&quot;">​</a></h2><h3 id="iframe-隔离的基线" tabindex="-1">iframe：隔离的基线 <a class="header-anchor" href="#iframe-隔离的基线" aria-label="Permalink to &quot;iframe：隔离的基线&quot;">​</a></h3><p>iframe 用浏览器进程/上下文级别的隔离，解决了“互不影响”。但它的代价是：</p><ul><li>子应用是独立文档，主应用无法直接操作其 DOM。</li><li>通信只能靠 <code>postMessage</code>。</li><li>路由、弹窗、加载态、高度自适应都要额外处理。</li><li>性能上多一份文档开销。</li></ul><p>即便如此，iframe 仍然是很多后台系统（尤其涉及第三方页面、强安全边界）的合理选择。</p><h3 id="single-spa-把-应用-抽象成生命周期" tabindex="-1">single-spa：把“应用”抽象成生命周期 <a class="header-anchor" href="#single-spa-把-应用-抽象成生命周期" aria-label="Permalink to &quot;single-spa：把“应用”抽象成生命周期&quot;">​</a></h3><p>single-spa 的关键贡献，是把子应用抽象成 <code>bootstrap / mount / unmount</code> 三个生命周期，并由根应用根据路由调度。它让“不同框架的子应用”有了统一接入方式。</p><p>但它只解决“调度”，不解决“隔离”。子应用仍然共享 <code>window</code> 与 <code>document</code>。</p><h3 id="qiankun-把隔离和加载补齐" tabindex="-1">qiankun：把隔离和加载补齐 <a class="header-anchor" href="#qiankun-把隔离和加载补齐" aria-label="Permalink to &quot;qiankun：把隔离和加载补齐&quot;">​</a></h3><p>qiankun 在 single-spa 之上补了三件事：</p><ol><li><strong>HTML Entry</strong>：子应用只需提供 URL，不需要在主应用里写 import。</li><li><strong>JS 沙箱</strong>：用 Proxy 拦截全局变量读写。</li><li><strong>样式隔离</strong>：通过选择器前缀或 Shadow DOM 限定作用域。</li></ol><p>这三件事让 qiankun 成为国内中后台最常见的选择之一。</p><h3 id="module-federation-换一条路" tabindex="-1">Module Federation：换一条路 <a class="header-anchor" href="#module-federation-换一条路" aria-label="Permalink to &quot;Module Federation：换一条路&quot;">​</a></h3><p>前面几代都在“运行时加载页面”。Module Federation 直接共享<strong>模块</strong>：</p><ul><li>子应用暴露组件或函数，主应用 <code>import</code> 远程模块。</li><li>依赖可以声明为 <code>shared</code>，避免重复加载。</li><li>不需要 HTML Entry，不需要沙箱。</li></ul><p>代价是构建耦合更强：远程模块的产物结构、共享依赖版本、部署顺序都需要约定。</p><h3 id="micro-app-与-wujie-降低接入成本" tabindex="-1">micro-app 与 wujie：降低接入成本 <a class="header-anchor" href="#micro-app-与-wujie-降低接入成本" aria-label="Permalink to &quot;micro-app 与 wujie：降低接入成本&quot;">​</a></h3><p>micro-app 用自定义标签 <code>&lt;micro-app&gt;</code> 接入，子应用几乎不用改生命周期；wujie 则把 JS 放进 iframe 执行、把 DOM 同步到 Shadow DOM，试图同时拿到“隔离”和“体验”。</p><h2 id="演进不是替代" tabindex="-1">演进不是替代 <a class="header-anchor" href="#演进不是替代" aria-label="Permalink to &quot;演进不是替代&quot;">​</a></h2><p>这七种方案不是“后者淘汰前者”。它们各自适合不同场景：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>强隔离、低改造           ←→           高体验、高集成</span></span>
<span class="line"><span>iframe   wujie   micro-app   qiankun   single-spa   Module Federation   Web Components</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>老系统多、团队弱、上线风险高：优先 iframe 或 wujie。</li><li>中后台、Vue/React 混合、需要沙箱：qiankun 或 micro-app。</li><li>组件级共享、构建体系成熟：Module Federation。</li><li>跨框架标准组件：Web Components。</li></ul><h2 id="一个判断原则" tabindex="-1">一个判断原则 <a class="header-anchor" href="#一个判断原则" aria-label="Permalink to &quot;一个判断原则&quot;">​</a></h2><blockquote><p>越靠近“运行时加载页面”，接入成本越低、隔离越依赖框架；越靠近“构建时共享模块”，依赖越明确、构建耦合越强。</p></blockquote><p>选型时先确定你要的是<strong>页面集成</strong>还是<strong>模块共享</strong>，再决定隔离强度。</p><p>下一步：<a href="/micro-frontend-docs/guide/decision-tree">选型决策树</a>。</p>`,30)])])}const m=e(o,[["render",r]]);export{h as __pageData,m as default};
